// Original saved SYMBOLS XML / actual LinksStep boundary. Explicit-grade conflict
// controls are separate kernels, not extra successful page observations.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.lang.reflect.*;
public class CompoundSymbolsProbe extends StemImageScheduleProbe {
 final Object book;public CompoundSymbolsProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static String symbols(Object sys)throws Exception{List<String> out=new ArrayList<>();Object sig=call(sys,"getSig");for(Object n:(Collection<?>)call(sig,"vertexSet")){String k=n.getClass().getSimpleName();if(k.equals("RestInter")||k.startsWith("Time")||k.contains("Dot"))out.add("{\"id\":"+call(n,"getId")+",\"kind\":\""+k+"\",\"shape\":\""+call(n,"getShape")+"\",\"bounds\":"+rect(call(n,"getBounds"))+",\"grade\":"+call(n,"getGrade")+",\"best_grade\":"+call(n,"getBestGrade")+",\"glyph\":"+physical(call(n,"getGlyph"))+"}");}return "["+String.join(",",out)+"]";}
 public void process(){try{
 Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet"),sys=((List<?>)call(sheet,"getSystems")).get(0),sig=call(sys,"getSig"),staff=((List<?>)call(sys,"getStaves")).get(0);
 String before=symbols(sys);Object rest=null;for(Object n:(Collection<?>)call(sig,"vertexSet"))if(n.getClass().getSimpleName().equals("RestInter")&&((java.awt.Rectangle)call(n,"getBounds")).x==391)rest=n;if(rest==null)throw new IllegalStateException("compound rest missing");Object glyph=call(rest,"getGlyph"),part=null;for(Object g:(Collection<?>)call(sys,"getGroupedGlyphs",Class.forName("org.audiveris.omr.glyph.GlyphGroup").getField("SYMBOL").get(null)))if(((java.awt.Rectangle)call(g,"getBounds")).equals(new java.awt.Rectangle(391,252,13,20)))part=g;if(part==null)throw new IllegalStateException("source part missing");
 Object links=Class.forName("org.audiveris.omr.step.OmrStep").getField("LINKS").get(null);call(links,"doit",sheet);String after=symbols(sys);
 Class<?> inter=Class.forName("org.audiveris.omr.sig.inter.RestInter");Constructor<?> ctor=inter.getConstructor(Class.forName("org.audiveris.omr.glyph.Glyph"),Class.forName("org.audiveris.omr.glyph.Shape"),Double.class,Class.forName("org.audiveris.omr.sheet.Staff"),Double.class);Object shape=Class.forName("org.audiveris.omr.glyph.Shape").getField("QUARTER_REST").get(null);
 Object reducer=Class.forName("org.audiveris.omr.sig.SigReducer").getConstructor(Class.forName("org.audiveris.omr.sheet.SystemInfo"),boolean.class).newInstance(sys,true);Method overlaps=reducer.getClass().getDeclaredMethod("detectOverlaps",List.class);overlaps.setAccessible(true);List<String> controls=new ArrayList<>();
 for(double[] grades:new double[][]{{.7,.6},{.6,.7},{.7,.7}}){Object a=ctor.newInstance(glyph,shape,grades[0],staff,2.),b=ctor.newInstance(part,shape,grades[1],staff,2.);call(sig,"addVertex",a);call(sig,"addVertex",b);call(a,"setContextualGrade",grades[0]);call(b,"setContextualGrade",grades[1]);overlaps.invoke(reducer,List.of(a,b));boolean exclusion=call(sig,"getExclusion",a,b)!=null;call(sig,"reduceExclusions");controls.add("{\"source_grade\":"+grades[0]+",\"target_grade\":"+grades[1]+",\"overlap_exclusion\":"+exclusion+",\"source_removed\":"+call(a,"isRemoved")+",\"target_removed\":"+call(b,"isRemoved")+"}");if(!(Boolean)call(a,"isRemoved"))call(a,"remove");if(!(Boolean)call(b,"isRemoved"))call(b,"remove");}
 Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"scope\":\"original image SYMBOLS, then saved-XML callback reload and actual LinksStep; separately explicit-grade overlap/reduceExclusions kernels on original compound and source part\",\"native_outputs_used\":false,\"before_LINKS\":"+before+",\"after_LINKS\":"+after+",\"compound_glyph\":"+physical(glyph)+",\"source_part\":"+physical(part)+",\"conflict_controls\":["+String.join(",",controls)+"]}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
